import java.util.*;
class Main {
  public static void main(String[] args) {
    Set<String> s = new HashSet<>();
    boolean first = s.add("a");
    boolean second = s.add(new String("a"));
    System.out.println(first + "," + second + "," + s.size());
  }
}

