import java.util.*;
class Item {
  String id;
  Item(String id) { this.id = id; }
  @Override public boolean equals(Object o) {
    return o instanceof Item && ((Item) o).id.equals(id);
  }
}
class Main {
  public static void main(String[] args) {
    Set<Item> s = new HashSet<>();
    s.add(new Item("a"));
    s.add(new Item("a"));
    System.out.println(s.size());
  }
}

